To create a native iOS habit tracker, we will use **Swift** and **SwiftUI**. This implementation follows the **MVVM (Model-View-ViewModel)** pattern.

### 1. The Model (`Habit.swift`)
First, define what a "Habit" looks like. We use `Identifiable` so it can be easily used in SwiftUI lists.

```swift
import Foundation

struct Habit: Identifiable, Codable {
    var id = UUID()
    var title: String
    var isCompleted: Bool = false
}
```

### 2. The ViewModel (`HabitViewModel.swift`)
This handles the logic and state of your habits.

```swift
import Foundation

class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = [] {
        didSet { saveHabits() }
    }

    init() { loadHabits() }

    func addHabit(title: String) {
        let newHabit = Habit(title: title)
        habits.append(newHabit)
    }

    func toggleHabit(id: UUID) {
        if let index = habits.firstIndex(where: { $0.id == id }) {
            habits[index].isCompleted.toggle()
        }
    }

    // Simple persistence using UserDefaults
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "SavedHabits")
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "SavedHabits"),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }
}
```

### 3. The View (`ContentView.swift`)
This is the UI layer that displays the list and allows interaction.

```swift
import SwiftUI

struct ContentView: View {
    @StateObject var viewModel = HabitViewModel()
    @State private var newHabitTitle = ""

    var body: some View {
        NavigationView {
            VStack {
                HStack {
                    TextField("New habit...", text: $newHabitTitle)
                        .textFieldStyle(RoundedBorderTextFieldStyle())

                    Button(action: {
                        guard !newHabitTitle.isEmpty else { return }
                        viewModel.addHabit(title: newHabitTitle)
                        newHabitTitle = ""
                    }) {
                        Image(systemName: "plus.circle.fill")
                            .font(.largeTitle)
                    }
                }
                .padding()

                List {
                    ForEach(viewModel.habits) { habit in
                        HStack {
                            Text(habit.title)
                            Spacer()
                            Image(systemName: habit.isCompleted ? "checkmark.circle.fill" : "circle")
                                .foregroundColor(habit.isCompleted ? .green : .gray)
                                .onTapGesture {
                                    viewModel.toggleHabit(id: habit.id)
                                }
                        }
                    }
                }
            }
            .navigationTitle("Habit Tracker")
        }
    }
}
```

### Key Concepts Used:
1.  **`@StateObject`**: Keeps the `HabitViewModel` alive for the lifecycle of the view.
2.  **`@Published`**: Automatically notifies the UI to refresh whenever the `habits` array changes.
3.  **`UserDefaults`**: A lightweight way to persist data locally without setting up a full database like CoreData or SwiftData.
4.  **`List` & `ForEach`**: The standard SwiftUI way to render dynamic collections of data.

