We use the `navigator.onLine` API to trigger a sync whenever the connection returns.

```javascript
// useSync.js
import { useEffect } from 'react';
import { db } from './db';

export const useSync = () => {
  const syncData = async () => {
    const pending = await db.surveys.where('status').equals('pending').toArray();

    for (const survey of pending) {
      try {
        await fetch('/api/surveys', {
          method: 'POST',
          body: JSON.stringify(survey)
        });
        await db.surveys.update(survey.id, { status: 'synced' });
      } catch (e) {
        console.error("Sync failed, will retry later", e);
      }
    }
  };

  useEffect(() => {
    window.addEventListener('online', syncData);
    return () => window.removeEventListener('online', syncData);
  }, []);
};
```

### 3. The Survey Form (Component)
The form saves data to the local DB immediately, regardless of connectivity.

```jsx
