    const surveyEntry = {
      ...data,
      status: navigator.onLine ? 'synced' : 'pending',
      updatedAt: Date.now()
    };

    await db.surveys.add(surveyEntry);

    if (navigator.onLine) {
      // Trigger immediate sync logic here
    } else {
      alert("Saved offline! Data will sync when you're back online.");
    }
  };

