### 2. The Sync Hook
This hook manages the background sync process.

```javascript
// useSync.js
import { useEffect } from 'react';
import { db } from './db';

export const useSync = () => {
  const syncData = async () => {
    const pending = await db.surveys.where('status').equals('pending').toArray();

    if (pending.length === 0) return;

    try {
      const response = await fetch('/api/surveys/bulk', {
        method: 'POST',
        body: JSON.stringify(pending),
      });

      if (response.ok) {
        // Mark as synced
        await db.surveys.where('status').equals('pending').modify({ status: 'synced' });
        console.log('Sync successful');
      }
    } catch (err) {
      console.log('Still offline, will retry later');
    }
  };

  useEffect(() => {
    window.addEventListener('online', syncData);
    return () => window.removeEventListener('online', syncData);
  }, []);
};
```

