  const survey = { ...data, synced: 0 }; // 0 = false
  await db.surveys.add(survey);

  if (navigator.onLine) {
    syncData();
  }
};

export const syncData = async () => {
  const unsynced = await db.surveys.where('synced').equals(0).toArray();

  for (const item of unsynced) {
    try {
      await fetch('/api/surveys', {
        method: 'POST',
        body: JSON.stringify(item)
      });
      await db.surveys.update(item.id, { synced: 1 });
    } catch (e) {
      console.error("Sync failed, will retry later", e);
    }
  }
};
```

