### 2. Database Setup (`db.js`)
First, define the schema. We add a `synced` flag to every survey entry.

```javascript
import Dexie from 'dexie';

export const db = new Dexie('SurveyDatabase');
db.version(1).stores({
  surveys: '++id, name, data, synced' // synced: 0 (false) or 1 (true)
});
```

---

### 3. Saving Data Offline
When the user submits a survey, save it to the local DB immediately.

```javascript
async function saveSurvey(surveyData) {
  const isOnline = navigator.onLine;

  const entry = {
    ...surveyData,
    synced: isOnline ? 1 : 0
  };

  await db.surveys.add(entry);

  if (isOnline) {
    syncData(); // Attempt immediate sync
  } else {
    alert("Saved locally. Will sync when back online.");
  }
}
```

---

### 4. The Sync Engine
This function finds all items where `synced === 0` and pushes them to your API.

```javascript
async function syncData() {
  const unsynced = await db.surveys.where('synced').equals(0).toArray();

  for (const item of unsynced) {
    try {
      const response = await fetch('/api/surveys', {
        method: 'POST',
        body: JSON.stringify(item)
      });

      if (response.ok) {
        // Mark as synced in local DB
        await db.surveys.update(item.id, { synced: 1 });
      }
    } catch (err) {
      console.error("Sync failed for item", item.id);
    }
  }
}
```

