#### B. The Sync Logic
This function runs whenever the app detects a network connection.

```javascript
// services/syncService.js
import { database } from './database';

export const syncSurveys = async () => {
  const pendingSurveys = await database.get('surveys')
    .query(Q.where('status', 'pending'))
    .fetch();

  for (const survey of pendingSurveys) {
    try {
      const response = await fetch('https://api.yoursurvey.com/submit', {
        method: 'POST',
        body: JSON.stringify(survey),
      });

      if (response.ok) {
        await database.write(async () => {
          await survey.update(s => { s.status = 'synced'; });
        });
      }
    } catch (e) {
      console.log("Still offline, will retry later.");
    }
  }
};
```

#### C. Connectivity Listener
Use `@react-native-community/netinfo` to trigger the sync automatically when the user regains internet.

```javascript
// App.js
import NetInfo from "@react-native-community/netinfo";

useEffect(() => {
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncSurveys(); // Trigger sync when back online
    }
  });
  return () => unsubscribe();
}, []);
```

