### 3. Implementation: The Sync Manager
This service handles the logic of checking connectivity and pushing data.

```javascript
import * as Network from 'expo-network';
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

export const syncData = async () => {
  const networkState = await Network.getNetworkStateAsync();
  if (!networkState.isConnected) return;

  // 1. Fetch unsynced records
  db.transaction(tx => {
    tx.executeSql(
      'SELECT * FROM surveys WHERE synced = 0',
      [],
      (_, { rows }) => {
        rows._array.forEach(async (record) => {
          try {
            // 2. Push to your API
            const response = await fetch('https://api.yoursurvey.com/submit', {
              method: 'POST',
              body: record.data,
            });

            if (response.ok) {
              // 3. Mark as synced locally
              db.transaction(tx => {
                tx.executeSql('UPDATE surveys SET synced = 1 WHERE id = ?', [record.id]);
              });
            }
          } catch (err) {
            console.log("Sync failed for record:", record.id);
          }
        });
      }
    );
  });
};
```

