  const data = document.getElementById('surveyData').value;
  await (await dbPromise).add('surveys', { data, timestamp: Date.now() });
  alert('Saved locally!');
  syncData(); // Attempt sync
}

// Sync logic
async function syncData() {
  if (!navigator.onLine) return;

  const db = await dbPromise;
  const tx = db.transaction('surveys', 'readwrite');
  const store = tx.objectStore('surveys');
  const allData = await store.getAll();

  for (const item of allData) {
    try {
      // Replace with your actual API endpoint
      await fetch('/api/sync', {
        method: 'POST',
        body: JSON.stringify(item)
      });
      await store.delete(item.id); // Remove from local after success
    } catch (e) {
      console.error("Sync failed", e);
    }
  }
}

// Listen for reconnection
window.addEventListener('online', () => {
  document.getElementById('status').innerText = "Status: Online";
  syncData();
});

window.addEventListener('offline', () => {
  document.getElementById('status').innerText = "Status: Offline (Saving locally)";
});
```

