import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { PlusCircle, Activity } from 'lucide-react';

export default function Dashboard() {
  const [data, setData] = useState([
    { time: '10:00', value: 30 },
    { time: '10:05', value: 45 },
    { time: '10:10', value: 25 },
  ]);

  const [inputValue, setInputValue] = useState('');

  // Simulate real-time data incoming every 5 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      const newValue = Math.floor(Math.random() * 100);
      const newTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
      setData(prev => [...prev.slice(-9), { time: newTime, value: newValue }]);
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const newTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setData(prev => [...prev, { time: newTime, value: parseInt(inputValue) }]);
    setInputValue('');
  };

  return (
    <div className="p-8 bg-gray-50 min-h-screen">
      <h1 className="text-2xl font-bold mb-6 flex items-center gap-2">
        <Activity /> Real-Time Analytics
      </h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Chart Section */}
        <div className="md:col-span-2 bg-white p-6 rounded-xl shadow-sm border">
          <h2 className="font-semibold mb-4">Live Performance</h2>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="time" />
                <YAxis />
                <Tooltip />
                <Line type="monotone" dataKey="value" stroke="#4f46e5" strokeWidth={2} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Form Section */}
        <div className="bg-white p-6 rounded-xl shadow-sm border">
          <h2 className="font-semibold mb-4">Add Data Point</h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <input
              type="number"
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              placeholder="Enter value (0-100)"
              className="w-full p-2 border rounded focus:ring-2 focus:ring-indigo-500 outline-none"
              required
            />
            <button className="w-full bg-indigo-600 text-white py-2 rounded flex items-center justify-center gap-2 hover:bg-indigo-700">
              <PlusCircle size={18} /> Add Entry
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}
```

### Key Features of this Implementation:

1.  **Recharts Integration**: Uses `ResponsiveContainer` to ensure the chart scales perfectly with the browser window.
2.  **State Management**: The `data` array acts as the "source of truth." Both the automatic `setInterval` (simulating a backend socket) and the `handleSubmit` function (user input) update the same state, triggering an instant UI re-render.
3.  **Real-time Simulation**: The `useEffect` hook handles the background data polling. In a production app, you would replace the `setInterval` logic with a **WebSocket** connection (e.g., `socket.io-client`).
4.  **Tailwind CSS**: Provides a clean, responsive layout using a grid system (`grid-cols-1 md:grid-cols-3`).
5.  **Lucide Icons**: Adds professional-grade iconography for better UX.

