        const ctx = document.getElementById('myChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: { labels: [], datasets: [{ label: 'Live Feed', data: [], borderColor: '#3b82f6' }] },
            options: { responsive: true }
        });

        // 1. Real-time simulation
        setInterval(() => {
            const now = new Date().toLocaleTimeString();
            chart.data.labels.push(now);
            chart.data.datasets[0].data.push(Math.floor(Math.random() * 100));
            if(chart.data.labels.length > 10) { chart.data.labels.shift(); chart.data.datasets[0].data.shift(); }
            chart.update();
        }, 1000);

        // 2. Form Handling
        document.getElementById('dataForm').addEventListener('submit', (e) => {
            e.preventDefault();
            const val = document.getElementById('valInput').value;
            alert("Data submitted: " + val);
            // You would typically send this to an API here
        });
    </script>
</body>
</html>
```

