<!DOCTYPE html>
<html lang="en">
<head>
    <script src="https://cdn.tailwindcss.com"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</head>
<body class="bg-gray-100 p-8">
    <div class="max-w-4xl mx-auto">
        <h1 class="text-2xl font-bold mb-4">Live Dashboard</h1>

        <!-- Form -->
        <div class="bg-white p-4 rounded shadow mb-6">
            <input id="dataInput" type="number" placeholder="Enter value" class="border p-2 rounded">
            <button onclick="addData()" class="bg-blue-500 text-white px-4 py-2 rounded">Add Data</button>
        </div>

