            if(chart.data.labels.length > 10) { // Keep only last 10 points
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }
            chart.update();
        }

        // 3. Real-time simulation (auto-update every 2 seconds)
        setInterval(updateChart, 2000);
    </script>
