    <canvas id="heatmap"></canvas>

    <script>
        const canvas = document.getElementById('heatmap');
        const ctx = canvas.getContext('2d');
        let width, height;

        // Mock Data: Array of stocks
        let stocks = Array.from({length: 100}, (_, i) => ({
            symbol: `STK${i}`,
            price: Math.random() * 100,
            change: (Math.random() - 0.5) * 10
        }));

        // Zoom/Pan state
        let transform = d3.zoomIdentity;

        function resize() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
            draw();
        }

        function draw() {
            ctx.clearRect(0, 0, width, height);

            // Calculate grid layout
            const cols = Math.ceil(Math.sqrt(stocks.length));
            const cellW = width / cols;
            const cellH = height / Math.ceil(stocks.length / cols);

            stocks.forEach((d, i) => {
                const x = (i % cols) * cellW;
                const y = Math.floor(i / cols) * cellH;

                // Apply Zoom/Pan
                const tx = x * transform.k + transform.x;
                const ty = y * transform.k + transform.y;
                const tw = cellW * transform.k;
                const th = cellH * transform.k;

                // Color based on change
                ctx.fillStyle = d.change >= 0 ? `rgb(0, ${100 + d.change * 20}, 0)` : `rgb(${100 + Math.abs(d.change) * 20}, 0, 0)`;
                ctx.fillRect(tx, ty, tw - 1, th - 1);

                // Text labels (only if zoomed in enough)
                if (transform.k > 1.5) {
                    ctx.fillStyle = "white";
                    ctx.fillText(d.symbol, tx + 5, ty + 15);
                }
            });
        }

        // Zoom behavior
        const zoom = d3.zoom().on('zoom', (event) => {
            transform = event.transform;
            draw();
        });
        d3.select(canvas).call(zoom);

        // Real-time update simulation
        setInterval(() => {
            stocks.forEach(s => s.change += (Math.random() - 0.5));
            draw();
        }, 2000);

        window.addEventListener('resize', resize);
        resize();
    </script>
</body>
</html>
```

