        const canvas = document.getElementById('heatmap');
        const ctx = canvas.getContext('2d');
        const width = window.innerWidth;
        const height = window.innerHeight;
        canvas.width = width;
        canvas.height = height;

        // 1. Mock Data: 200 stocks
        let stocks = Array.from({length: 200}, (_, i) => ({
            symbol: `STK${i}`,
            value: Math.random() * 100,
            change: (Math.random() - 0.5) * 10
        }));

        // 2. D3 Treemap Layout
        const treemap = d3.treemap().size([width, height]).padding(1);

        function draw(transform = d3.zoomIdentity) {
            ctx.clearRect(0, 0, width, height);

            const root = d3.hierarchy({children: stocks})
                .sum(d => d.value)
                .sort((a, b) => b.value - a.value);
            treemap(root);

            root.leaves().forEach(d => {
                // Apply zoom/pan transform
                const x = d.x0 * transform.k + transform.x;
                const y = d.y0 * transform.k + transform.y;
                const w = (d.x1 - d.x0) * transform.k;
                const h = (d.y1 - d.y0) * transform.k;

                // Color based on change
                ctx.fillStyle = d.data.change > 0 ? `rgb(0, ${100 + d.data.change*15}, 0)` : `rgb(${100 - d.data.change*15}, 0, 0)`;
                ctx.fillRect(x, y, w, h);
                ctx.strokeStyle = "white";
                ctx.strokeRect(x, y, w, h);
            });
        }

        // 3. Zoom/Pan Behavior
        const zoom = d3.zoom().scaleExtent([1, 8]).on('zoom', (e) => draw(e.transform));
        d3.select(canvas).call(zoom);

        // 4. Real-time Updates (Simulated)
        setInterval(() => {
            stocks.forEach(s => s.change += (Math.random() - 0.5));
            draw(d3.zoomTransform(canvas));
        }, 2000);

        draw();
    </script>
</body>
</html>
