### 1. The HTML Structure
We need a container for the heatmap and a simple script to handle the data.

```html
<!DOCTYPE html>
<html>
<head>
    <script src="https://d3js.org/d3.v7.min.js"></script>
    <style>
        .cell { stroke: #fff; stroke-width: 0.5px; cursor: pointer; }
        .label { font-size: 10px; fill: white; pointer-events: none; }
        #heatmap { width: 800px; height: 600px; border: 1px solid #ccc; overflow: hidden; }
    </style>
</head>
<body>
    <div id="heatmap"></div>
    <script src="app.js"></script>
</body>
</html>
```

### 2. The Implementation (`app.js`)
This script initializes a Treemap layout, adds zoom/pan behavior, and simulates real-time price updates.

```javascript
const width = 800, height = 600;
const svg = d3.select("#heatmap")
    .append("svg")
    .attr("width", width)
    .attr("height", height);

// 1. Initial Data
let data = {
    name: "Market",
    children: [
        { name: "AAPL", value: 150, change: 0.02 },
        { name: "GOOGL", value: 2800, change: -0.01 },
        { name: "MSFT", value: 300, change: 0.05 },
        { name: "AMZN", value: 3300, change: -0.03 }
    ]
};

// 2. Setup Zoom/Pan
const zoom = d3.zoom().scaleExtent([1, 8]).on("zoom", (event) => {
    container.attr("transform", event.transform);
});
svg.call(zoom);

const container = svg.append("g");

// 3. Render Function
function updateHeatmap(data) {
    const root = d3.hierarchy(data).sum(d => d.value);
    d3.treemap().size([width, height]).padding(1)(root);

    const cells = container.selectAll(".cell").data(root.leaves(), d => d.data.name);

    cells.join("rect")
        .attr("class", "cell")
        .attr("x", d => d.x0)
        .attr("y", d => d.y0)
        .attr("width", d => d.x1 - d.x0)
        .attr("height", d => d.y1 - d.y0)
        .attr("fill", d => d.data.change >= 0 ? "green" : "red");

    // Add Labels
    container.selectAll(".label").data(root.leaves(), d => d.data.name)
        .join("text")
        .attr("class", "label")
        .attr("x", d => d.x0 + 5)
        .attr("y", d => d.y0 + 15)
        .text(d => `${d.data.name} (${(d.data.change * 100).toFixed(1)}%)`);
}

// 4. Real-time Simulation
setInterval(() => {
    data.children.forEach(d => d.change += (Math.random() - 0.5) * 0.02);
    updateHeatmap(data);
}, 2000);

updateHeatmap(data);
```

### Key Technical Considerations for Production:

1.  **Performance (Canvas vs. SVG):**
    *   The code above uses **SVG**. This is fine for < 500 stocks.
    *   If you need to display thousands of stocks, switch the rendering logic to **HTML5 Canvas**. D3 can still calculate the layout, but you would use `context.fillRect()` instead of appending DOM elements.

2.  **Data Updates:**
    *   In a real app, replace `setInterval` with a **WebSocket** connection.
    *   Use `d3.transition()` to animate the color changes smoothly rather than snapping instantly.

3.  **Zoom/Pan UX:**
    *   The current implementation zooms the entire SVG. For a better UX, you might want to implement "Click-to-Zoom" (where clicking a sector zooms into that specific hierarchy level) rather than free-form panning.

4.  **Color Scaling:**
    *   Instead of hardcoded red/green, use a D3 Diverging Scale:
        ```javascript
        const color = d3.scaleDiverging(d3.interpolateRdYlGn)
                        .domain([-0.05, 0, 0.05]); // -5% to +5%
        ```

### Next Steps
*   **Add Tooltips:** Use `d3-tip` to show detailed price info on hover.
*   **Responsive Design:** Use a `ResizeObserver` to update the `width` and `height` variables when the browser window changes size.

