        // 2. Zoom/Pan Logic
        const zoom = d3.zoom().scaleExtent([1, 10]).on("zoom", (event) => {
            render(event.transform);
        });
        canvas.call(zoom);

        // 3. Render Loop
        function render(transform = d3.zoomIdentity) {
            ctx.clearRect(0, 0, width, height);
            ctx.save();
            ctx.translate(transform.x, transform.y);
            ctx.scale(transform.k, transform.k);

            data.forEach(d => {
                ctx.fillStyle = color(d.val);
                ctx.fillRect(d.x, d.y, 12, 12);
            });
            ctx.restore();
        }

        // 4. Real-time Update Simulation
        setInterval(() => {
            // Randomly update 5 stocks
