```javascript
const width = 800, height = 600;
const data = Array.from({ length: 50 }, (_, i) => ({
    id: i,
    ticker: `STK${i}`,
    price: Math.random() * 100,
    change: (Math.random() - 0.5) * 10
}));

const svg = d3.select("#heatmap")
    .append("svg")
    .attr("width", width)
    .attr("height", height);

const g = svg.append("g");

// Color scale: Red (negative) to Green (positive)
const color = d3.scaleLinear().domain([-5, 0, 5]).range(["red", "gray", "green"]);

function render() {
    const rects = g.selectAll(".cell").data(data, d => d.id);

    rects.enter()
        .append("rect")
        .attr("class", "cell")
        .merge(rects)
        .attr("x", (d, i) => (i % 10) * 80)
        .attr("y", (d, i) => Math.floor(i / 10) * 120)
        .attr("width", 75)
        .attr("height", 115)
        .attr("fill", d => color(d.change));
}

// Zoom/Pan behavior
const zoom = d3.zoom()
    .scaleExtent([0.5, 5])
    .on("zoom", (event) => g.attr("transform", event.transform));

svg.call(zoom);

// Simulate real-time updates
setInterval(() => {
    data.forEach(d => d.change += (Math.random() - 0.5));
    render();
}, 2000);

render();
```

