    </style>
</head>
<body>

<div id="container"><div id="grid"></div></div>

<script>
    const grid = document.getElementById('grid');
    const cells = [];

    // 1. Initialize Grid
    for (let i = 0; i < 100; i++) {
        const div = document.createElement('div');
        div.className = 'cell';
        grid.appendChild(div);
        cells.push(div);
    }

    // 2. Real-time Update Logic
    function update() {
        cells.forEach(cell => {
            const val = Math.random() * 2 - 1; // -1 to 1
            cell.style.backgroundColor = val > 0 ? `rgba(0, 255, 0, ${val})` : `rgba(255, 0, 0, ${Math.abs(val)})`;
            cell.innerText = (val * 100).toFixed(0) + '%';
        });
        setTimeout(update, 1000);
    }

    // 3. Zoom/Pan Logic
    let scale = 1, posX = 0, posY = 0;
    const container = document.getElementById('container');

    container.onwheel = (e) => {
        e.preventDefault();
        scale += e.deltaY * -0.001;
        scale = Math.min(Math.max(.5, scale), 4);
        grid.style.transform = `scale(${scale}) translate(${posX}px, ${posY}px)`;
    };

    update();
</script>
</body>
</html>
```

