<canvas id="heatmap" width="600" height="400" style="border:1px solid #000; cursor:crosshair"></canvas>

<script>
const canvas = document.getElementById('heatmap');
const ctx = canvas.getContext('2d');
const size = 10; // 10x10 grid
const cellSize = 50;
let stocks = Array.from({length: size * size}, () => ({ price: 100, change: 0 }));

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    stocks.forEach((s, i) => {
        const x = (i % size) * cellSize;
        const y = Math.floor(i / size) * cellSize;
        // Color based on price change (Red to Green)
        ctx.fillStyle = s.change >= 0 ? `rgb(0, ${100 + s.change*50}, 0)` : `rgb(${100 - s.change*50}, 0, 0)`;
        ctx.fillRect(x, y, cellSize - 2, cellSize - 2);
    });
}

// Simulate real-time updates
setInterval(() => {
    stocks.forEach(s => {
        s.change = (Math.random() - 0.5) * 2;
        s.price += s.change;
    });
    draw();
}, 500);

// Simple Zoom/Pan Interaction
let scale = 1;
canvas.addEventListener('wheel', (e) => {
    scale += e.deltaY * -0.01;
    canvas.style.transform = `scale(${scale})`;
});
</script>
</body>
</html>
```

