import React, { useState } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

const initialTasks = {
  todo: [{ id: '1', title: 'Design System' }, { id: '2', title: 'Setup Database' }],
  done: [{ id: '3', title: 'Project Init' }]
};

function Task({ id, title }) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id });
  const style = { transform: CSS.Transform.toString(transform), transition };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="p-4 mb-2 bg-white shadow rounded cursor-grab">
      {title}
    </div>
  );
}

export default function App() {
  const [tasks, setTasks] = useState(initialTasks);

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (!over) return;
    // Logic to move items between arrays would go here
    console.log(`Moved ${active.id} to ${over.id}`);
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="flex gap-8 p-10 bg-gray-100 min-h-screen">
        {Object.entries(tasks).map(([column, items]) => (
          <div key={column} className="w-64 bg-gray-200 p-4 rounded">
            <h2 className="font-bold mb-4 uppercase">{column}</h2>
            <SortableContext items={items} strategy={verticalListSortingStrategy}>
              {items.map(task => <Task key={task.id} id={task.id} title={task.title} />)}
            </SortableContext>
          </div>
        ))}
      </div>
    </DndContext>
  );
}
```

