### 3. The Drag-and-Drop Board
This component handles the UI and the logic for moving tasks between columns.

```jsx
import React, { useState, useEffect } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { db } from './firebase';
import { collection, onSnapshot, doc, updateDoc } from 'firebase/firestore';

const TaskBoard = () => {
  const [tasks, setTasks] = useState([]);

  // Real-time listener for Firebase updates
  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, "tasks"), (snapshot) => {
      setTasks(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
    return unsubscribe;
  }, []);

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      // Logic to update Firebase with new order
      const oldIndex = tasks.findIndex(t => t.id === active.id);
      const newIndex = tasks.findIndex(t => t.id === over.id);
      const newTasks = arrayMove(tasks, oldIndex, newIndex);
      setTasks(newTasks);

      // Update Firestore here...
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="board">
        {['To Do', 'In Progress', 'Done'].map(status => (
          <div key={status} className="column">
            <h2>{status}</h2>
            {tasks.filter(t => t.status === status).map(task => (
              <div key={task.id} className="task-card">{task.title}</div>
            ))}
          </div>
        ))}
      </div>
    </DndContext>
  );
};
```

