import React, { useState, useEffect } from 'react';
import { DndContext } from '@dnd-kit/core';
import { ref, onValue, set } from "firebase/database";
import { db } from './firebase';

const Board = () => {
  const [tasks, setTasks] = useState([]);

  // Real-time sync
  useEffect(() => {
    const tasksRef = ref(db, 'tasks/');
    onValue(tasksRef, (snapshot) => {
      const data = snapshot.val();
      setTasks(data ? Object.values(data) : []);
    });
  }, []);

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      // Update logic: Update Firebase, which triggers the useEffect above
      const updatedTasks = tasks.map(t => 
        t.id === active.id ? { ...t, status: over.id } : t
      );
      set(ref(db, 'tasks/'), updatedTasks);
    }
  };

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div style={{ display: 'flex', gap: '20px' }}>
        {['Todo', 'Doing', 'Done'].map(status => (
          <div key={status} style={{ border: '1px solid #ccc', padding: '10px' }}>
