import React, { useEffect, useState } from 'react';
import { DndContext } from '@dnd-kit/core';
import { createClient } from '@supabase/supabase-js';

const supabase = createClient('YOUR_URL', 'YOUR_KEY');

export default function KanbanBoard() {
  const [tasks, setTasks] = useState([]);

  // 1. Fetch and Subscribe to Real-time updates
  useEffect(() => {
    const fetchTasks = async () => {
      const { data } = await supabase.from('tasks').select('*');
      setTasks(data);
    };
    fetchTasks();

    // Real-time subscription
    const channel = supabase.channel('tasks').on(
      'postgres_changes', { event: '*', schema: 'public', table: 'tasks' },
      (payload) => {
        if (payload.eventType === 'UPDATE') {
          setTasks(prev => prev.map(t => t.id === payload.new.id ? payload.new : t));
        }
      }
    ).subscribe();

    return () => supabase.removeChannel(channel);
  }, []);

  // 2. Handle Drag End
  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over) return;

    const taskId = active.id;
    const newStatus = over.id; // Assuming drop zones have IDs like 'todo', 'done'

    // Optimistic UI update
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: newStatus } : t));

    // Sync to Database
    await supabase.from('tasks').update({ status: newStatus }).eq('id', taskId);
  };

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div className="flex gap-4 p-8">
        {['todo', 'in-progress', 'done'].map(status => (
          <div key={status} id={status} className="w-64 bg-gray-100 p-4 rounded">
            <h2 className="font-bold uppercase mb-4">{status}</h2>
            {tasks.filter(t => t.status === status).map(task => (
              <div key={task.id} className="bg-white p-2 mb-2 shadow rounded">
                {task.content}
              </div>
            ))}
          </div>
        ))}
      </div>
    </DndContext>
  );
}
```

### Key Architectural Components

#### A. Real-time Sync Logic
The `supabase.channel` subscription is the "secret sauce." Whenever any user moves a card, the database triggers a broadcast event. Every other connected client receives this event and updates their local `tasks` state automatically, creating the "live" collaboration effect.

#### B. Optimistic UI
In `handleDragEnd`, we update the local state *before* the database call finishes. This makes the application feel instantaneous to the user. If the database call fails, you would typically add a `catch` block to revert the state.

#### C. Scaling Considerations
1.  **Authentication:** Use `supabase.auth` to ensure users can only move tasks if they belong to the specific project workspace.
2.  **Performance:** As the list grows, use `react-window` or `react-virtualized` to render only the visible tasks.
3.  **Conflict Resolution:** If two users move the same card at the exact same time, Supabase's PostgreSQL backend handles the row-level locking, ensuring the final state is consistent.

