import { initializeApp } from "https://www.gstatic.com/firebasejs/9.x/firebase-app.js";
import { getFirestore, collection, onSnapshot, doc, updateDoc } from "https://www.gstatic.com/firebasejs/9.x/firebase-firestore.js";

const firebaseConfig = { /* YOUR FIREBASE CONFIG HERE */ };
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

// Initialize Drag and Drop
const columns = document.querySelectorAll('#todo, #done');
columns.forEach(col => {
    new Sortable(col, {
        group: 'shared',
        onEnd: (evt) => {
            const taskId = evt.item.id;
            const newStatus = evt.to.id;
            updateDoc(doc(db, "tasks", taskId), { status: newStatus });
        }
    });
});

// Real-time Sync
onSnapshot(collection(db, "tasks"), (snapshot) => {
    snapshot.forEach((doc) => {
        const task = doc.data();
        const el = document.getElementById(doc.id) || createTaskElement(doc.id, task);
        document.getElementById(task.status).appendChild(el);
    });
});

function createTaskElement(id, task) {
    const div = document.createElement('div');
    div.id = id;
    div.className = "bg-white p-3 mb-2 rounded shadow cursor-move";
    div.innerText = task.title;
    return div;
}
```

