import { collection, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from './firebase';

const Column = ({ id, title, tasks }) => (
  <div style={{ background: '#eee', padding: '10px', width: '200px' }}>
    <h3>{title}</h3>
    {tasks.filter(t => t.status === id).map(task => (
      <div key={task.id} style={{ margin: '5px', padding: '10px', background: 'white' }}>
        {task.title}
      </div>
    ))}
  </div>
);

export default function KanbanBoard() {
  const [tasks, setTasks] = useState([]);

  // Real-time listener
  useEffect(() => {
    const unsub = onSnapshot(collection(db, 'tasks'), (snapshot) => {
      setTasks(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
    return unsub;
  }, []);

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over) return;

    // Update Firestore directly
    const taskRef = doc(db, 'tasks', active.id);
    await updateDoc(taskRef, { status: over.id });
  };

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div style={{ display: 'flex', gap: '20px' }}>
        <Column id="todo" title="To Do" tasks={tasks} />
        <Column id="doing" title="In Progress" tasks={tasks} />
        <Column id="done" title="Done" tasks={tasks} />
      </div>
    </DndContext>
  );
}
```

### 4. Key Features Explained

*   **Real-time Collaboration:** By using `onSnapshot` from Firestore, every time a user drags a card, the database updates. Because the other clients are listening to that same collection, their UI updates instantly without a page refresh.
*   **Drag-and-Drop:** `dnd-kit` provides the sensor logic. When `handleDragEnd` triggers, we identify which task was moved and update its `status` field in the database.
*   **Scalability:**
    *   **Authentication:** Integrate `firebase/auth` to track *who* moved the task.
    *   **Optimistic UI:** Currently, the UI waits for the database to update. You can improve this by updating the local state immediately and rolling back if the server request fails.
    *   **Styling:** Use **Tailwind CSS** for a professional look.

### 5. Next Steps to Production
1.  **Add Task Creation:** Add a form that uses `addDoc` from Firestore to push new tasks to the collection.
2.  **Optimistic Updates:** Use `useMutation` (if using React Query) or local state management to make the drag-and-drop feel "snappy" before the server confirms the change.
3.  **User Presence:** Use Firebase Realtime Database "Presence" to show which users are currently viewing the board.
