### 3. Frontend Implementation (Core Logic)

This snippet demonstrates a basic Kanban board using `@dnd-kit`.

```jsx
import React, { useState, useEffect } from 'react';
import { DndContext } from '@dnd-kit/core';
import { supabase } from './supabaseClient';

const KanbanBoard = () => {
  const [tasks, setTasks] = useState([]);

  // Fetch tasks and subscribe to changes
  useEffect(() => {
    const fetchTasks = async () => {
      const { data } = await supabase.from('tasks').select('*');
      setTasks(data);
    };

    fetchTasks();

    // Real-time listener
    const channel = supabase.channel('tasks')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'tasks' }, 
        (payload) => fetchTasks())
      .subscribe();

    return () => supabase.removeChannel(channel);
  }, []);

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!over) return;

    // Update local state immediately
    const updatedTasks = tasks.map(t => 
      t.id === active.id ? { ...t, status: over.id } : t
    );
    setTasks(updatedTasks);

    // Persist to DB
    await supabase.from('tasks').update({ status: over.id }).eq('id', active.id);
  };

  return (
    <DndContext onDragEnd={handleDragEnd}>
      <div className="flex gap-4 p-4">
        {['todo', 'in-progress', 'done'].map(status => (
          <div key={status} className="w-64 bg-gray-100 p-4 rounded">
            <h2 className="font-bold uppercase">{status}</h2>
            {tasks.filter(t => t.status === status).map(task => (
              <div key={task.id} className="bg-white p-2 my-2 shadow rounded">
                {task.content}
              </div>
            ))}
          </div>
        ))}
      </div>
    </DndContext>
  );
};
```

