```javascript
import { initializeApp } from "firebase/app";
import { getDatabase, ref, onValue, update } from "firebase/database";

const firebaseConfig = { /* Your Firebase Config */ };
const app = initializeApp(firebaseConfig);
const db = getDatabase(app);

// 1. Listen for real-time updates
onValue(ref(db, 'tasks'), (snapshot) => {
  const tasks = snapshot.val();
  renderTasks(tasks);
});

// 2. Drag and Drop Handlers
function allowDrop(ev) { ev.preventDefault(); }

function drag(ev) {
  ev.dataTransfer.setData("taskId", ev.target.id);
}

function drop(ev) {
  ev.preventDefault();
  const taskId = ev.dataTransfer.getData("taskId");
  const newStatus = ev.currentTarget.id; // The column ID

  // Update Firebase (triggers UI update for everyone)
  update(ref(db, 'tasks/' + taskId), { status: newStatus });
}

// 3. Render function
function renderTasks(tasks) {
  // Clear columns and re-append tasks based on status
  // ... logic to map tasks to their respective column divs
}
```

