            if (h == tail.load(std::memory_order_acquire)) continue; // Wait for data

            // Process order logic here (Matching, Risk Checks)
            auto& order = ringBuffer[h];
            // ... execute matching logic ...

            head.store((h + 1) % RING_SIZE, std::memory_order_release);
        }
    }
