```cpp
#include <iostream>
#include <atomic>
#include <vector>
#include <thread>

// A simple lock-free ring buffer for inter-thread communication
template<typename T, size_t Size>
class RingBuffer {
    T buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Empty
        item = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};

struct MarketData { double price; int quantity; };

void strategy_thread(RingBuffer<MarketData, 1024>& rb) {
    MarketData md;
    while (true) {
        if (rb.pop(md)) {
            // Logic: If price < threshold, send order
            if (md.price < 100.0) { /* Send Order */ }
        }
    }
}

int main() {
    RingBuffer<MarketData, 1024> rb;
    std::thread t1(strategy_thread, std::ref(rb));

    // Pin thread to core 1
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(1, &cpuset);
    pthread_setaffinity_np(t1.native_handle(), sizeof(cpu_set_t), &cpuset);

    // Simulate Market Data Feed
    while(true) {
        rb.push({99.5, 10});
    }
}
```

