#include <vector>
#include <iostream>

// A simple lock-free ring buffer for IPC
template<typename T, size_t Size>
class RingBuffer {
    std::vector<T> buffer{Size};
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false;
        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        item = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};

struct Order { int id; double price; };

int main() {
    RingBuffer<Order, 1024> orderQueue;

    // Producer Thread (Gateway)
    orderQueue.push({1, 150.25});

    // Consumer Thread (Matching Engine)
