    public long timestamp;
    public byte[] payload;
    public void set(byte[] payload) {
        this.payload = payload;
        this.timestamp = System.nanoTime();
    }
}

// 2. The High-Performance Router
public class MessageRouter {
    private final Disruptor<MessageEvent> disruptor;

    public MessageRouter(int bufferSize) {
        this.disruptor = new Disruptor<>(
            MessageEvent::new, 
            bufferSize, 
            Executors.defaultThreadFactory()
        );

        // Add latency monitoring handler
        disruptor.handleEventsWith((event, sequence, endOfBatch) -> {
            long latency = System.nanoTime() - event.timestamp;
            // Log latency metrics (use a lock-free histogram in production)
            process(event, latency);
        });

        disruptor.start();
    }

