This example uses a **Lock-Free Ring Buffer** (the foundation of the LMAX Disruptor pattern) to pass messages between a Producer and a Consumer.

```cpp
#include <atomic>
#include <vector>
#include <iostream>
#include <chrono>

struct Message {
    uint64_t id;
    uint64_t timestamp;
    char payload[64];
};

// A simple lock-free ring buffer for high-throughput
template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Empty
        msg = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};
```

