### 2. Implementation (C++ with Disruptor Pattern)
We use a lock-free Ring Buffer to pass messages between the "Ingress" thread and the "Router" thread.

```cpp
#include <atomic>
#include <vector>
#include <chrono>
#include <iostream>

// Simple Message Structure
struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
    char payload[64];
};

// Lock-free Ring Buffer (Simplified)
template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        if ((t + 1) % Size == head.load(std::memory_order_acquire)) return false;
        buffer[t] = msg;
        tail.store((t + 1) % Size, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};
```

