```java
import java.util.concurrent.atomic.AtomicLong;

public class MessageRingBuffer {
    private final Message[] buffer;
    private final int mask;
    private final AtomicLong cursor = new AtomicLong(-1);

    public MessageRingBuffer(int size) {
        // Size must be power of 2 for bitwise masking
        this.buffer = new Message[size];
        this.mask = size - 1;
        for (int i = 0; i < size; i++) buffer[i] = new Message();
    }

    public void publish(long id, String payload) {
        long index = cursor.incrementAndGet();
        Message msg = buffer[(int) (index & mask)];
        msg.setData(id, payload, System.nanoTime());
    }
}
```

