    private long count = 0;

    public void record(long startTimeNanos) {
        long latency = System.nanoTime() - startTimeNanos;
        totalLatency += latency;
        count++;

        if (count % 1_000_000 == 0) {
            System.out.printf("Avg Latency: %.2f ns%n", (double) totalLatency / count);
        }
    }
}
```

