#include <iostream>
#include <vector>
#include <atomic>
#include <thread>
#include <chrono>
#include <x86intrin.h> // For __rdtsc()

struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
    char payload[64];
};

// A simple Lock-Free Ring Buffer (SPSC)
template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false;
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};

// Router Logic
void router_thread(RingBuffer<1024>& rb) {
    Message msg;
    while (true) {
        if (rb.pop(msg)) {
            uint64_t now = __rdtsc();
            // Latency = current time - message creation time
            uint64_t latency = now - msg.timestamp_ns;

            // In production, use a histogram for latency distribution
            // instead of printing to stdout (which is slow)
        }
    }
}
```

