#include <iostream>
#include <atomic>
#include <vector>
#include <chrono>
#include <immintrin.h> // For _mm_pause

// A simple lock-free ring buffer node
struct Message {
    uint64_t id;
    uint64_t timestamp;
    char payload[64];
};

template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false;
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};

// Latency Monitoring
inline uint64_t get_cycles() {
    return __rdtsc();
}

void consumer(RingBuffer<1024>& rb) {
    Message msg;
    while (true) {
        if (rb.pop(msg)) {
            uint64_t latency = get_cycles() - msg.timestamp;
            // Log latency periodically to avoid I/O in the hot path
        } else {
            _mm_pause(); // CPU hint to save power/prevent pipeline stalls
        }
    }
}
```

