#include <iostream>
#include <atomic>
#include <vector>
#include <chrono>
#include <thread>

// Minimal Lock-Free Ring Buffer
template<size_t Size>
struct RingBuffer {
    struct Message { uint64_t id; uint64_t timestamp; };
    Message buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

    bool push(uint64_t id) {
        size_t t = tail.load(std::memory_order_relaxed);
        if ((t + 1) % Size == head.load(std::memory_order_acquire)) return false;
        buffer[t] = {id, (uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count()};
        tail.store((t + 1) % Size, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};

RingBuffer<1024> rb;

void consumer() {
    uint64_t total_latency = 0, count = 0;
    while (true) {
        RingBuffer<1024>::Message msg;
        if (rb.pop(msg)) {
            auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            total_latency += (now - msg.timestamp);
            if (++count % 1000000 == 0) 
                std::cout << "Avg Latency: " << (total_latency / count) / 1000 << "us" << std::endl;
        }
    }
}

int main() {
    std::thread(consumer).detach();
    uint64_t i = 0;
    while (true) { // Producer
        if (!rb.push(i++)) std::this_thread::yield();
    }
}
