#include <iostream>
#include <atomic>
#include <vector>
#include <chrono>
#include <thread>

// Cache line alignment to prevent false sharing
struct alignas(64) Message {
    uint64_t id;
    uint64_t timestamp;
    char data[64];
};

const size_t RING_SIZE = 1024 * 1024; // Must be power of 2
Message ring[RING_SIZE];
std::atomic<size_t> head{0};
std::atomic<size_t> tail{0};

// PRODUCER: Pin to Core 0
void producer() {
    uint64_t count = 0;
    while (true) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) & (RING_SIZE - 1);

        if (next_t != head.load(std::memory_order_acquire)) {
            ring[t].id = ++count;
            ring[t].timestamp = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            tail.store(next_t, std::memory_order_release);
        }
    }
}

// CONSUMER: Pin to Core 1
void consumer() {
    size_t h = 0;
    while (true) {
        size_t t = tail.load(std::memory_order_acquire);
        if (h != t) {
            auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            auto latency = now - ring[h].timestamp;

            // Minimal processing
            if (ring[h].id % 1000000 == 0) 
                std::cout << "Latency: " << latency << " ns | ID: " << ring[h].id << std::endl;

            h = (h + 1) & (RING_SIZE - 1);
            head.store(h, std::memory_order_release);
        }
    }
}

int main() {
    std::thread t1(producer);
    std::thread t2(consumer);
    t1.join(); t2.join();
    return 0;
}
```

