// A simple lock-free SPSC Ring Buffer
template<typename T, size_t Capacity>
class RingBuffer {
    T buffer[Capacity];
    std::atomic<size_t> head{0}, tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        if ((t + 1) % Capacity == head.load(std::memory_order_acquire)) return false;
        buffer[t] = item;
        tail.store((t + 1) % Capacity, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        item = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return true;
    }
};

struct Message {
    uint64_t timestamp;
    uint64_t id;
};

// High-precision latency measurement
inline uint64_t now_ns() {
    return std::chrono::high_resolution_clock::now().time_since_epoch().count();
}

int main() {
    RingBuffer<Message, 65536> rb;
    std::atomic<bool> running{true};

    // Consumer Thread
    std::thread consumer([&]() {
        Message msg;
        uint64_t total_latency = 0;
        uint64_t count = 0;
        while (running) {
            if (rb.pop(msg)) {
                total_latency += (now_ns() - msg.timestamp);
                count++;
                if (count % 1000000 == 0) 
                    std::cout << "Avg Latency: " << (total_latency / count) << "ns\n";
            }
        }
    });

    // Producer Thread
    for (uint64_t i = 0; i < 10000000; ++i) {
        while (!rb.push({now_ns(), i})) { /* Busy wait (backpressure) */ }
    }

    running = false;
    consumer.join();
    return 0;
}
```

