This example uses C++ with `std::atomic` to create a single-producer, single-consumer (SPSC) lock-free ring buffer.

### The Architecture
1.  **Ring Buffer:** A pre-allocated circular array to avoid memory allocation during runtime.
2.  **Memory Barriers:** Using `std::memory_order_acquire/release` to ensure CPU cache coherency without heavy mutex locks.
3.  **Latency Tracking:** Using `rdtsc` (Read Time-Stamp Counter) for nanosecond-precision measurement.

### Minimal Implementation (C++17)

```cpp
#include <iostream>
#include <atomic>
#include <vector>
#include <chrono>

// High-resolution timestamp for latency monitoring
inline uint64_t rdtsc() {
    unsigned int lo, hi;
    __asm__ __volatile__ ("rdtsc" : "=a" (lo), "=d" (hi));
    return ((uint64_t)hi << 32) | lo;
}

struct Message {
    uint64_t timestamp;
    uint64_t seq;
    char data[64];
};

// Lock-free SPSC Ring Buffer
template<size_t Capacity>
class RingBuffer {
    Message buffer[Capacity];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Capacity;
        if (next_t == head.load(std::memory_order_acquire)) return false;
        buffer[t] = msg;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return true;
    }
};

// --- Execution ---
int main() {
    RingBuffer<1024> rb;
    const int count = 1'000'000;

    // Consumer Thread
    auto consumer = std::thread([&]() {
        Message m;
        for(int i = 0; i < count; ++i) {
            while(!rb.pop(m));
            uint64_t latency = rdtsc() - m.timestamp;
            if(i % 100000 == 0) std::cout << "Latency: " << latency << " cycles\n";
        }
    });

    // Producer Thread
    for(int i = 0; i < count; ++i) {
        Message m = {rdtsc(), (uint64_t)i, "payload"};
        while(!rb.push(m));
    }

    consumer.join();
    return 0;
}
```

### Key Optimizations for "Millions per Second"

1.  **CPU Affinity:** Use `pthread_setaffinity_np` to pin the Producer and Consumer threads to specific physical CPU cores. This prevents the OS scheduler from moving threads and flushing L1/L2 caches.
2.  **False Sharing:** Note the `alignas(64)` on the atomic head/tail pointers. This ensures they reside on different cache lines, preventing "cache line bouncing" where cores fight for ownership of the same memory address.
3.  **Hugepages:** For massive buffers, use `mmap` with `MAP_HUGETLB` to reduce TLB (Translation Lookaside Buffer) misses.
4.  **Busy-Wait Polling:** Never use `std::condition_variable` or `sleep`. Always busy-poll the ring buffer. This keeps the CPU core in a "hot" state, ready to process the next message immediately.
5.  **Zero-Copy:** In a production system, pass pointers or offsets to the ring buffer rather than copying the `Message` struct.

