```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

// Packet filtering logic: Drop everything except specific EtherType (e.g., 0x0800 for IPv4)
static inline int is_allowed(struct rte_mbuf *pkt) {
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(pkt, struct rte_ether_hdr *);
    return (ntohs(eth_hdr->ether_type) == RTE_ETHER_TYPE_IPV4);
}

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL init\n");

    // 2. Create Memory Pool for packets
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
                                    MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Initialize Port (Simplified - assumes port 0)
    // In production, you must configure rte_eth_conf and rte_eth_dev_configure

    // 4. Main Processing Loop (The "Fast Path")
    struct rte_mbuf *bufs[BURST_SIZE];
    while (1) {
        // Poll packets from NIC (Zero-copy)
        const uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);

        if (unlikely(nb_rx == 0)) continue;

        uint16_t nb_tx = 0;
        struct rte_mbuf *tx_bufs[BURST_SIZE];

        for (int i = 0; i < nb_rx; i++) {
            // Packet-level filtering
            if (is_allowed(bufs[i])) {
                // Forwarding: Add to transmit queue
                tx_bufs[nb_tx++] = bufs[i];
            } else {
                // Drop packet
                rte_pktmbuf_free(bufs[i]);
            }
        }

        // Send allowed packets
        if (nb_tx > 0) {
            rte_eth_tx_burst(0, 0, tx_bufs, nb_tx);
        }
    }
    return 0;
}
```

### Key Techniques for Ultra-Low Latency

1.  **Busy Polling:** Notice the `while(1)` loop. We do not use interrupts. Interrupts cause context switches (kernel to user space), which take microseconds. Polling keeps the CPU core at 100% usage but ensures the NIC is checked every few nanoseconds.
2.  **Zero-Copy:** We use `rte_mbuf` structures. The NIC writes directly into these memory buffers via DMA (Direct Memory Access). We never copy the packet data; we only pass pointers.
3.  **CPU Pinning (Affinity):** To achieve consistent latency, you must pin the process to a specific CPU core using `taskset` or `pthread_setaffinity_np`. This prevents the OS scheduler from moving your process and causing cache misses.
4.  **Hugepages:** Standard 4KB pages lead to frequent TLB misses. Using 2MB or 1GB hugepages ensures the memory mapping for the packet buffers stays in the CPU's Translation Lookaside Buffer.
5.  **Branch Prediction:** The use of `unlikely()` hints to the compiler that the "no packets received" branch is rare, optimizing the instruction pipeline for the "packet received" path.

