#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

static const struct rte_eth_conf port_conf_default = {
    .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN }
};

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL init\n");

    // 2. Create Memory Pool for packets
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
        MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Initialize Port (Simplified)
    uint16_t portid = 0;
    rte_eth_dev_configure(portid, 1, 1, &port_conf_default);
    rte_eth_rx_queue_setup(portid, 0, RX_RING_SIZE, rte_socket_id(), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(portid, 0, TX_RING_SIZE, rte_socket_id(), NULL);
    rte_eth_dev_start(portid);

    // 4. Main Processing Loop
    struct rte_mbuf *bufs[32];
    while (1) {
        const uint16_t nb_rx = rte_eth_rx_burst(portid, 0, bufs, 32);

        for (int i = 0; i < nb_rx; i++) {
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);

            // --- PACKET FILTERING LOGIC ---
            // Example: Drop all non-IPv4 packets
            if (ntohs(eth_hdr->ether_type) != RTE_ETHER_TYPE_IPV4) {
                rte_pktmbuf_free(bufs[i]);
                continue;
            }

            // --- FORWARDING LOGIC ---
            // Send packet back out (or to another port)
            rte_eth_tx_burst(portid, 0, &bufs[i], 1);
        }
    }
    return 0;
}
```

### Key Strategies for Ultra-Low Latency

1. **Busy Polling:** The code above uses a `while(1)` loop. This keeps the CPU core at 100% usage, preventing the "wake-up" latency associated with interrupts.
2. **Zero-Copy:** DPDK uses `rte_mbuf` structures. The packet data stays in the same memory location from the moment it hits the NIC until it is sent out; you only pass pointers.
3. **CPU Isolation (Affinity):** Use `taskset` or `isolcpus` in your Linux boot parameters to dedicate specific CPU cores to your application. This prevents the OS scheduler from moving your thread, which causes cache invalidation.
4. **Hugepages:** Standard 4KB pages cause frequent TLB misses. Configure 1GB hugepages to ensure the entire packet buffer memory is mapped in the TLB.
5. **Avoid System Calls:** Never use `printf`, `malloc`, or `read/write` inside the main loop. These trigger context switches to the kernel. Use pre-allocated memory pools and lock-free rings.

