```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

// Simple packet filtering logic
static inline int is_packet_allowed(struct rte_mbuf *m) {
    // Example: Drop all non-IPv4 packets
    struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    return (rte_be_to_cpu_16(eth_hdr->ether_type) == RTE_ETHER_TYPE_IPV4);
}

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL init\n");

    // 2. Create a memory pool for packets
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
                                    MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Configure Ethernet Port (Simplified)
    struct rte_eth_conf port_conf = {0};
    rte_eth_dev_configure(0, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(0, 0, RX_RING_SIZE, rte_socket_id(), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(0, 0, TX_RING_SIZE, rte_socket_id(), NULL);
    rte_eth_dev_start(0);

    // 4. Main Processing Loop (Poll Mode)
    struct rte_mbuf *bufs[32];
    while (1) {
        const uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, 32);

        for (int i = 0; i < nb_rx; i++) {
            if (is_packet_allowed(bufs[i])) {
                // Forwarding: Send back out the same port (or swap port)
                rte_eth_tx_burst(0, 0, &bufs[i], 1);
            } else {
                // Drop packet
                rte_pktmbuf_free(bufs[i]);
            }
        }
    }
    return 0;
}
```

### Key Architectural Principles for Ultra-Low Latency

If you are building this for production, you must optimize beyond the code above:

1.  **CPU Isolation (Affinity):** Use `taskset` or `isolcpus` in the Linux boot parameters to pin your DPDK process to specific physical CPU cores. This prevents the OS scheduler from interrupting your packet processing loop.
2.  **Zero-Copy:** The `rte_mbuf` structure allows you to pass pointers to packet data across the system without ever copying the actual payload. Ensure your filtering logic only inspects headers without touching the payload memory.
3.  **Batching:** The `rte_eth_rx_burst` function retrieves packets in batches. While processing one-by-one is easier, batching improves instruction cache locality.
