```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

// Minimal packet filtering logic
static inline int filter_packet(struct rte_mbuf *m) {
    struct rte_ether_hdr *eth = rte_pktmbuf_mtod(m, struct rte_ether_hdr *);
    // Example: Drop if destination MAC starts with 0xDE:AD
    if ((eth->dst_addr.addr_bytes[0] == 0xDE) && (eth->dst_addr.addr_bytes[1] == 0xAD))
        return 0; // Drop
    return 1; // Forward
}

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 2. Configure Ethernet Device (Simplified for Port 0)
    struct rte_eth_conf port_conf = {0};
    rte_eth_dev_configure(0, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(0, 0, RX_RING_SIZE, rte_eth_dev_socket_id(0), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(0, 0, TX_RING_SIZE, rte_eth_dev_socket_id(0), NULL);
    rte_eth_dev_start(0);

    // 3. Main Loop (The "Fast Path")
    while (1) {
        struct rte_mbuf *bufs[32];
        uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, 32);

        for (int i = 0; i < nb_rx; i++) {
            if (filter_packet(bufs[i])) {
                rte_eth_tx_burst(0, 0, &bufs[i], 1);
            } else {
                rte_pktmbuf_free(bufs[i]);
            }
        }
    }
    return 0;
}
```

### Why this is "Ultra-Low Latency":

1.  **Zero-Copy:** The NIC writes directly into memory buffers (`mbufs`) that the application reads. No data is copied between kernel and user space.
2.  **Poll Mode Driver (PMD):** Instead of using interrupts (which cause expensive context switches), the application "polls" the NIC hardware registers in a tight loop. This keeps the CPU cache warm and eliminates interrupt latency.
3.  **Bypassing the Stack:** We ignore the TCP/IP stack entirely. We operate at Layer 2 (Ethernet frames), which is the fastest possible way to move data.
4.  **Hugepages:** By using 2MB or 1GB memory pages, we reduce TLB (Translation Lookaside Buffer) misses, which are a common source of jitter in high-speed networking.

