package main

import (
	"io"
	"os"
	"path/filepath"
)

// Rotator handles log rotation with a fixed memory buffer
type Rotator struct {
	BufferSize int64
}

func (r *Rotator) Rotate(srcPath, destPath string) error {
	// Open source file
	src, err := os.Open(srcPath)
	if err != nil {
		return err
	}
	defer src.Close()

	// Create destination file
	dest, err := os.OpenFile(destPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644)
	if err != nil {
		return err
	}
	defer dest.Close()

	// Allocate a strict, fixed-size buffer (e.g., 32KB)
	// This ensures memory usage does not scale with file size
	buf := make([]byte, r.BufferSize)

	// Stream data from src to dest
	_, err = io.CopyBuffer(dest, src, buf)
	if err != nil {
		return err
	}

	// Truncate original file to free disk space
	return os.Truncate(srcPath, 0)
}

func main() {
	rotator := &Rotator{BufferSize: 32 * 1024} // 32KB limit

	err := rotator.Rotate("/var/log/app.log", "/var/log/app.log.1")
	if err != nil {
		panic(err)
	}
}
```

