### 2. The Daemon Implementation (`main.rs`)
This daemon runs an asynchronous loop that samples system metrics at a high frequency without blocking the event loop.

```rust
use sysinfo::{CpuRefreshKind, RefreshKind, System};
use tokio::time::{self, Duration};
use log::{info, error};

struct Monitor {
    sys: System,
}

impl Monitor {
    fn new() -> Self {
        Self {
            // Configure refresh to only track what we need for performance
            sys: System::new_with_specifics(
                RefreshKind::new()
                    .with_cpu(CpuRefreshKind::everything())
                    .with_memory(),
            ),
        }
    }

    async fn run(&mut self) {
        let mut interval = time::interval(Duration::from_secs(1));

        loop {
            interval.tick().await;

            // Refresh only the specific components
            self.sys.refresh_cpu();
            self.sys.refresh_memory();

            let cpu_usage: f32 = self.sys.global_cpu_info().cpu_usage();
            let mem_used = self.sys.used_memory();

