use daemonize::Daemonize;
use std::fs::File;
use sysinfo::{CpuExt, System, SystemExt};
use tokio::time::{self, Duration};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // 1. Setup Logging
    let stdout = File::create("/tmp/daemon.out").unwrap();
    let stderr = File::create("/tmp/daemon.err").unwrap();

    // 2. Configure Daemon
    let daemonize = Daemonize::new()
        .pid_file("/tmp/monitor.pid")
        .stdout(stdout)
        .stderr(stderr)
        .privileged_action(|| "Daemon started");

    // 3. Detach from terminal
    match daemonize.start() {
        Ok(_) => println!("Daemonized successfully"),
        Err(e) => eprintln!("Error: {}", e),
    }

    // 4. Monitoring Loop
    run_monitor().await;

    Ok(())
}

async fn run_monitor() {
    let mut sys = System::new_all();
    let mut interval = time::interval(Duration::from_secs(2));

    loop {
        interval.tick().await;

        // Refresh system data
        sys.refresh_cpu();
        sys.refresh_memory();

        let cpu_usage = sys.global_cpu_info().cpu_usage();
        let mem_usage = sys.used_memory() as f64 / sys.total_memory() as f64 * 100.0;

        // In a real system, you would send this to a socket, 
        // database, or trigger alerts here.
        eprintln!(
            "System Stats -> CPU: {:.2}%, RAM: {:.2}%",
            cpu_usage, mem_usage
        );
    }
}
```

### Key High-Performance Considerations

1.  **Asynchronous I/O**: By using `tokio`, the daemon remains responsive. If you decide to add network reporting (e.g., sending metrics to a remote dashboard), the daemon won't hang while waiting for network packets.
2.  **Resource Refreshing**: `sysinfo` is efficient, but calling `refresh_all()` is expensive. Always call specific refresh methods (e.g., `refresh_cpu()`, `refresh_memory()`) to minimize syscall overhead.
3.  **Zero-Allocation Loops**: In the `run_monitor` loop, we reuse the `sys` object rather than re-instantiating it. This prevents heap fragmentation and reduces pressure on the allocator.
4.  **Graceful Shutdown**: For a production system, you should implement a signal handler (using `tokio::signal::ctrl_c`) to catch `SIGTERM` and `SIGINT` to clean up PID files and close database connections before exiting.

