use sysinfo::{CpuRefreshKind, RefreshKind, System};
use tokio::time::{self, Duration};
use log::{info, error};

struct Monitor {
    sys: System,
}

impl Monitor {
    fn new() -> Self {
        // Initialize with specific refresh kinds for performance
        let refresh_kind = RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory();

        Self {
            sys: System::new_with_specifics(refresh_kind),
        }
    }

    async fn run(&mut self) {
        let mut interval = time::interval(Duration::from_secs(2));

        loop {
            interval.tick().await;

            // Refresh only the metrics we care about
            self.sys.refresh_cpu();
            self.sys.refresh_memory();

            let cpu_usage: f32 = self.sys.global_cpu_info().cpu_usage();
            let mem_used = self.sys.used_memory() / 1024 / 1024; // MB

            info!("System Status: CPU: {:.2}% | RAM: {} MB", cpu_usage, mem_used);

            // Logic for resource management (e.g., killing runaway processes)
            if cpu_usage > 95.0 {
                self.handle_high_load();
            }
        }
    }

    fn handle_high_load(&self) {
        error!("High load detected! Triggering mitigation...");
        // Add logic to identify and throttle/kill processes here
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();
    info!("Starting System Monitor Daemon...");

    let mut monitor = Monitor::new();
    monitor.run().await;
}
```

### Key Performance Considerations

1.  **Selective Refreshing:** Notice the use of `RefreshKind`. Calling `sys.refresh_all()` is expensive because it iterates through every process and disk on the system. By specifying only CPU and Memory, you reduce the syscall overhead significantly.
2.  **Asynchronous I/O:** By using `tokio::time::interval`, the daemon sleeps efficiently between checks, consuming near-zero CPU cycles while idle.
3.  **Zero-Copy/Stack Allocation:** Rust avoids heap allocations in the hot path of the loop, ensuring the monitor itself doesn't become a source of system instability.
4.  **Systemd Integration:** To run this as a true daemon on Linux, you must create a service file at `/etc/systemd/system/monitor.service`:

```ini
[Unit]
Description=High Performance System Monitor
After=network.target

[Service]
ExecStart=/usr/local/bin/my_monitor_binary
Restart=always
User=root

[Install]
WantedBy=multi-user.target
```

### Advanced Optimization Tips
*   **eBPF:** If you need sub-millisecond monitoring or deep kernel-level visibility (e.g., tracking specific syscalls), look into the **[aya-rs](https://aya-rs.dev/)** library. It allows you to write eBPF programs in Rust that run inside the kernel, which is the gold standard for high-performance monitoring.
