use sysinfo::{CpuExt, System, SystemExt};
use tokio::time::{self, Duration};
use log::{info, warn};

struct Monitor {
    sys: System,
}

impl Monitor {
    fn new() -> Self {
        Self { sys: System::new_all() }
    }

    fn tick(&mut self) {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();
        let mem_used = self.sys.used_memory() / 1024 / 1024; // MB

        info!("System Load: {:.2}% | Memory Used: {} MB", cpu_usage, mem_used);

        // Logic for management: e.g., if cpu_usage > 90%, log a warning
        if cpu_usage > 90.0 {
            warn!("High CPU pressure detected!");
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();
    info!("Starting System Monitor Daemon...");

    let mut monitor = Monitor::new();
    let mut interval = time::interval(Duration::from_secs(2));

    loop {
        tokio::select! {
            _ = interval.tick() => {
                monitor.tick();
            }
            _ = tokio::signal::ctrl_c() => {
                info!("Shutdown signal received. Exiting...");
                break;
            }
        }
    }

    Ok(())
}
