use tokio::time::{sleep, Duration};
use nix::unistd::{fork, ForkResult, setsid};
use std::process::exit;

fn daemonize() {
    // Fork the process to run in the background
    match unsafe { fork() } {
        Ok(ForkResult::Parent { .. }) => exit(0), // Exit parent
        Ok(ForkResult::Child) => {
            setsid().expect("Failed to create new session"); // Become session leader
        }
        Err(_) => panic!("Fork failed"),
    }
}

#[tokio::main]
