    if (pid > 0) exit(EXIT_SUCCESS);
    if (setsid() < 0) exit(EXIT_FAILURE);

    // Redirect standard streams to /dev/null
    freopen("/dev/null", "r", stdin);
    freopen("/dev/null", "w", stdout);
    freopen("/dev/null", "w", stderr);
}

int main() {
    daemonize();
    openlog("sys_monitor", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Monitor daemon started.");

    while (1) {
        // High-performance monitoring: Read /proc/stat
        // In a real app, use epoll() if monitoring sockets/files
        FILE* fp = fopen("/proc/stat", "r");
        if (fp) {
            char buffer[128];
            fgets(buffer, sizeof(buffer), fp);
            syslog(LOG_DEBUG, "CPU Stats: %s", buffer);
            fclose(fp);
        }

        sleep(5); // Adjust frequency based on performance needs
    }

    closelog();
    return 0;
}
