    unsigned int rcvd, i;
    uint32_t idx_rx = 0;

    while (keep_running) {
        // 1. Poll the RX ring for new packets
        rcvd = xsk_ring_cons__peek(&xsk->rx, BATCH_SIZE, &idx_rx);
