#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <sys/socket.h>
#include <sys/mman.h>
#include <net/if.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#define RING_FRAMES 2048
#define FRAME_SIZE 4096

int setup_socket(const char *iface) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));

    // 1. Set up memory-mapped ring buffer
    struct tpacket_req req = {
        .tp_block_size = FRAME_SIZE * 16,
        .tp_frame_size = FRAME_SIZE,
        .tp_block_nr = 128,
        .tp_frame_nr = RING_FRAMES
    };
    setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req));

    // 2. Bind to interface
    struct sockaddr_ll sa = { .sll_family = AF_PACKET, .sll_ifindex = if_nametoindex(iface) };
    bind(fd, (struct sockaddr *)&sa, sizeof(sa));

    // 3. Enable Fanout for multi-core scaling
    int fanout_arg = (getpid() << 16) | PACKET_FANOUT_HASH;
    setsockopt(fd, SOL_PACKET, PACKET_FANOUT, &fanout_arg, sizeof(fanout_arg));

    return fd;
}
```

