#include <sys/mman.h>
#include <net/if.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#define RING_FRAMES 2048
#define FRAME_SIZE 2048

int setup_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));

    // 1. Set up memory-mapped ring buffer
    struct tpacket_req req = {
        .tp_block_size = FRAME_SIZE * RING_FRAMES,
        .tp_frame_size = FRAME_SIZE,
        .tp_block_nr = 1,
        .tp_frames_per_block = RING_FRAMES
    };

    setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req));

    // 2. Enable Fanout for multi-core scaling
    int fanout_arg = (getpid() << 16) | PACKET_FANOUT_HASH;
    setsockopt(fd, SOL_PACKET, PACKET_FANOUT, &fanout_arg, sizeof(fanout_arg));

    // 3. Bind to interface
    struct ifreq ifr;
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ);
    ioctl(fd, SIOCGIFINDEX, &ifr);

    struct sockaddr_ll sll = { .sll_family = AF_PACKET, .sll_ifindex = ifr.ifr_ifindex };
    bind(fd, (struct sockaddr *)&sll, sizeof(sll));

    return fd;
}
```

