#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define FRAME_SIZE 2048
#define FRAME_COUNT 4096

int main() {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));

    // Setup mmap ring buffer for zero-copy
    struct tpacket_req req = {
        .tp_block_size = FRAME_SIZE * FRAME_COUNT,
        .tp_block_nr = 1,
        .tp_frame_size = FRAME_SIZE,
        .tp_frame_nr = FRAME_COUNT
    };

    setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req));
    uint8_t *ring = mmap(NULL, req.tp_block_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

    struct tpacket_hdr *header = (struct tpacket_hdr *)ring;
    int frame_idx = 0;

    printf("Monitoring traffic...\n");

    while (1) {
        // Wait for packet (TP_STATUS_USER means kernel has filled this frame)
        while (!(header[frame_idx].tp_status & TP_STATUS_USER)) {
            usleep(1); // In production, use poll() or busy-wait
        }

        // Process packet directly in the ring buffer memory
        unsigned char *packet = (unsigned char *)header + header[frame_idx].tp_offset;
        printf("Captured packet of size: %d\n", header[frame_idx].tp_snaplen);

        // Reset status to hand back to kernel
        header[frame_idx].tp_status = TP_STATUS_KERNEL;
        frame_idx = (frame_idx + 1) % FRAME_COUNT;
    }

    return 0;
}
```

### Critical Architecture Requirements for Gigabit+

To scale this to 10Gbps or 40Gbps, the code above is only the foundation. You must implement these three architectural patterns:

#### 1. Zero-Copy (DPDK or AF_XDP)
The example above uses `AF_PACKET` mmap, which is good for 1Gbps. For 10Gbps+, use **AF_XDP** (eXpress Data Path) or **DPDK**. These allow the NIC to DMA packets directly into your application's memory space, completely bypassing the Linux kernel networking stack.

#### 2. CPU Pinning and NUMA Awareness
*   **Pinning:** Use `pthread_setaffinity_np` to lock your processing thread to a specific CPU core.
*   **NUMA:** Ensure the NIC is physically connected to the PCIe bus of the CPU socket where your application is running. If the NIC is on Socket 0 and your app is on Socket 1, the QPI/UPI bus latency will destroy your performance.

#### 3. Lockless Data Structures
Never use `mutex` or `spinlock` in the hot path. 
