#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_BME280.h>

// Configuration
#define SENSOR_READ_INTERVAL 1000 // Read every 1000ms
Adafruit_BME280 bme;

// Variables for processing
unsigned long lastReadTime = 0;
float filteredTemperature = 0.0;
const float alpha = 0.2; // Smoothing factor (0 < alpha < 1)

void setup() {
  Serial.begin(115200);

  if (!bme.begin(0x76)) {
    Serial.println("Could not find BME280 sensor!");
    while (1);
  }
  Serial.println("Sensor initialized.");
}

void loop() {
  unsigned long currentTime = millis();

  // Non-blocking timer
  if (currentTime - lastReadTime >= SENSOR_READ_INTERVAL) {
    lastReadTime = currentTime;

    // 1. Read raw data
    float rawTemp = bme.readTemperature();

    // 2. Process data (Exponential Moving Average Filter)
    // Formula: New = (alpha * raw) + ((1 - alpha) * old)
    filteredTemperature = (alpha * rawTemp) + ((1.0 - alpha) * filteredTemperature);

    // 3. Output/Act
    Serial.print("Raw: "); Serial.print(rawTemp);
    Serial.print(" | Filtered: "); Serial.println(filteredTemperature);

    // 4. Safety/Logic Check
    if (filteredTemperature > 40.0) {
      triggerAlarm();
    }
  }
}

void triggerAlarm() {
