#include <Arduino.h>

// Configuration
const int SENSOR_PIN = A0;
const float THRESHOLD_TEMP = 45.0; // Celsius
const unsigned long READ_INTERVAL = 100; // ms

// Variables for processing
float movingAverage = 0;
const float alpha = 0.1; // Smoothing factor (0 < alpha < 1)
unsigned long lastReadTime = 0;

/**
 * Converts raw ADC value to Celsius
 * Assuming 10-bit ADC (0-1023) and 5V reference
 */
float convertToCelsius(int rawValue) {
    float voltage = rawValue * (5.0 / 1023.0);
    return voltage * 100.0; // Example conversion for LM35
}

void setup() {
    Serial.begin(9600);
    pinMode(SENSOR_PIN, INPUT);
}

void loop() {
    unsigned long currentTime = millis();

    // Non-blocking timer: Read sensor every 100ms
    if (currentTime - lastReadTime >= READ_INTERVAL) {
        lastReadTime = currentTime;

        // 1. Read raw data
        int rawValue = analogRead(SENSOR_PIN);

        // 2. Process: Exponential Moving Average (Low-pass filter)
        // Formula: y[n] = alpha * x[n] + (1 - alpha) * y[n-1]
        float currentTemp = convertToCelsius(rawValue);
        movingAverage = (alpha * currentTemp) + ((1.0 - alpha) * movingAverage);

        // 3. Logic: Threshold check
        if (movingAverage > THRESHOLD_TEMP) {
            Serial.print("ALERT: High Temp! ");
        }

        // 4. Output
        Serial.print("Temp: ");
        Serial.println(movingAverage);
    }
}
```

