  sensorBuffer[bufferIndex] = rawValue;
  bufferIndex = (bufferIndex + 1) % NUM_SAMPLES;

  float sum = 0;
  for (int i = 0; i < NUM_SAMPLES; i++) {
    sum += sensorBuffer[i];
  }
  return sum / NUM_SAMPLES;
}
