    total = total - readings[readIndex];    // Subtract oldest
    readings[readIndex] = rawValue;         // Add new
    total = total + readings[readIndex];    // Add new to total
    readIndex++;                            // Increment index

    if (readIndex >= NUM_READINGS) {
      readIndex = 0;                        // Wrap around
    }

    float average = total / (float)NUM_READINGS;

    // 3. Output/Action
    processData(average);
  }
}

void processData(float value) {
