#define SENSOR_BUFFER_SIZE 5

// Simple Moving Average Filter
uint16_t process_sensor_data(uint16_t new_sample) {
    static uint16_t buffer[SENSOR_BUFFER_SIZE] = {0};
    static uint8_t index = 0;
    static uint32_t sum = 0;

    // Subtract oldest, add newest
    sum -= buffer[index];
    buffer[index] = new_sample;
    sum += buffer[index];

    // Increment index
    index = (index + 1) % SENSOR_BUFFER_SIZE;

    return (uint16_t)(sum / SENSOR_BUFFER_SIZE);
}

