  sensorBuffer[bufferIndex] = newValue;
  bufferIndex = (bufferIndex + 1) % SAMPLES_COUNT;

  float sum = 0;
  for(int i = 0; i < SAMPLES_COUNT; i++) sum += sensorBuffer[i];
  return sum / SAMPLES_COUNT;
}

void loop() {
