/*
 * Firmware: Sensor Data Processor
 * Target: Microcontroller (Arduino/ESP32/STM32)
 */

// Constants
const int SENSOR_PIN = A0;
const unsigned long READ_INTERVAL = 100; // Read every 100ms
const int FILTER_SIZE = 10;              // Moving average window

// Variables
unsigned long lastReadTime = 0;
float readings[FILTER_SIZE];
int readIndex = 0;
float total = 0;

void setup() {
  Serial.begin(115200);
  // Initialize filter array
  for (int i = 0; i < FILTER_SIZE; i++) readings[i] = 0;
}

void loop() {
  unsigned long currentTime = millis();

  // Non-blocking timer
  if (currentTime - lastReadTime >= READ_INTERVAL) {
    lastReadTime = currentTime;

    // 1. Read raw data
    int rawValue = analogRead(SENSOR_PIN);

    // 2. Convert to physical unit (e.g., Voltage -> Celsius)
    float voltage = rawValue * (3.3 / 1023.0);
    float temperatureC = (voltage - 0.5) * 100;

    // 3. Process: Moving Average Filter
    total = total - readings[readIndex];
    readings[readIndex] = temperatureC;
    total = total + readings[readIndex];
    readIndex = (readIndex + 1) % FILTER_SIZE;
    float averageTemp = total / FILTER_SIZE;

    // 4. Output/Act
    Serial.print("Raw: "); Serial.print(rawValue);
    Serial.print(" | Filtered Temp: "); Serial.println(averageTemp);
  }
}
```

