  int rawValue = analogRead(sensorPin);

  // 2. PROCESS: Moving Average Filter
  total = total - readings[readIndex];    // Subtract oldest reading
  readings[readIndex] = rawValue;         // Add new reading
  total = total + readings[readIndex];    // Add new reading to total
  readIndex = (readIndex + 1) % numReadings; // Advance index

  float average = total / (float)numReadings; // Calculate average

  // 3. OUTPUT: Send processed data to Serial Monitor
