#include <iostream>
#include <chrono>
#include <thread>

// Simple Kalman Filter for Sensor Fusion
class StateEstimator {
    float estimate = 0.0f;
    float error_est = 1.0f;
    float error_meas = 0.5f; // Sensor noise
    float q = 0.01f;         // Process noise

public:
    float update(float imu_accel, float encoder_vel) {
        // Simple fusion: Weighted average based on uncertainty
        float measurement = (imu_accel + encoder_vel) / 2.0f; 

        // Kalman Gain
        float kalman_gain = error_est / (error_est + error_meas);
        estimate = estimate + kalman_gain * (measurement - estimate);
        error_est = (1 - kalman_gain) * error_est + fabs(estimate) * q;

        return estimate;
    }
};

// PID Controller
class PIDController {
    float kp, ki, kd, prev_error = 0, integral = 0;
public:
    PIDController(float p, float i, float d) : kp(p), ki(i), kd(d) {}

    float compute(float setpoint, float measured_value, float dt) {
        float error = setpoint - measured_value;
        integral += error * dt;
        float derivative = (error - prev_error) / dt;
        prev_error = error;
        return (kp * error) + (ki * integral) + (kd * derivative);
    }
};

int main() {
    StateEstimator fusion;
    PIDController motor_pid(1.0, 0.1, 0.05);

    const int frequency = 100; // 100Hz
    const auto dt = std::chrono::milliseconds(1000 / frequency);

    float target_velocity = 5.0f;

    while (true) {
        auto start_time = std::chrono::steady_clock::now();

        // 1. SENSE: Get raw data from hardware
        float imu_data = read_imu(); 
