#include <mutex>
#include <atomic>

// Simple PID Controller structure
struct PID {
    double kp, ki, kd;
    double prev_error = 0, integral = 0;

    double compute(double setpoint, double measured, double dt) {
        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return (kp * error) + (ki * integral) + (kd * derivative);
    }
};

class RobotController {
private:
    std::atomic<bool> running{true};
    std::mutex sensor_mutex;

    // Sensor Fusion Data
    double current_position = 0.0;
    double target_position = 10.0;

    PID pid = {1.0, 0.1, 0.05};

public:
    // Simulated Sensor Fusion Thread (e.g., IMU + Encoder)
    void sensor_fusion_loop() {
        while (running) {
            // Simulate reading hardware
            double new_data = 0.5; // Placeholder for sensor fusion logic

            std::lock_guard<std::mutex> lock(sensor_mutex);
            current_position += new_data; 

            std::this_thread::sleep_for(std::chrono::milliseconds(5)); // 200Hz
        }
    }

    // Real-time Control Loop
    void control_loop() {
        auto last_time = std::chrono::steady_clock::now();

        while (running) {
            auto now = std::chrono::steady_clock::now();
            double dt = std::chrono::duration<double>(now - last_time).count();
            last_time = now;

            double pos;
            {
                std::lock_guard<std::mutex> lock(sensor_mutex);
                pos = current_position;
            }

            // Compute Control Signal
            double output = pid.compute(target_position, pos, dt);

            // Send to Motor Driver (Hardware Abstraction Layer)
            // motor_driver.set_pwm(output);

            std::cout << "Pos: " << pos << " | Output: " << output << std::endl;

            // Maintain 100Hz frequency
            std::this_thread::sleep_until(now + std::chrono::milliseconds(10));
        }
    }

    void stop() { running = false; }
};

int main() {
    RobotController robot;
    std::thread t1(&RobotController::sensor_fusion_loop, &robot);
    std::thread t2(&RobotController::control_loop, &robot);

    t1.join();
    t2.join();
    return 0;
}
```

