    float buffer[WINDOW_SIZE];
    int head;
    float sum;
    float sum_sq;
} MovingStats;

// Initialize the statistics tracker
void init_stats(MovingStats *s) {
    s->head = 0;
    s->sum = 0;
    s->sum_sq = 0;
    for(int i = 0; i < WINDOW_SIZE; i++) s->buffer[i] = 0;
}

// Process new sample and return 1 if anomaly detected
int process_sample(MovingStats *s, float new_val) {
    // Remove old value from stats
    float old_val = s->buffer[s->head];
    s->sum -= old_val;
    s->sum_sq -= (old_val * old_val);

    // Add new value
    s->buffer[s->head] = new_val;
    s->sum += new_val;
    s->sum_sq += (new_val * new_val);

    // Calculate Mean and Std Dev
    float mean = s->sum / WINDOW_SIZE;
    float variance = (s->sum_sq / WINDOW_SIZE) - (mean * mean);
    float std_dev = sqrtf(variance > 0 ? variance : 0);

    // Detect Anomaly (Z-Score)
    int is_anomaly = (fabsf(new_val - mean) > (THRESHOLD * std_dev + 0.1f));

    // Advance circular buffer
    s->head = (s->head + 1) % WINDOW_SIZE;

    return is_anomaly;
}

int main() {
