            if (abs(sample - mean) > (THRESHOLD * stdDev)) {
                isAnomaly = true;
            }
        }

        // Update circular buffer
        buffer[index] = sample;
        index = (index + 1) % BUFFER_SIZE;
        if (index == 0) bufferFull = true;

        return isAnomaly;
    }
};

