### 2. The Implementation

```cpp
#include <iostream>

// Configuration Constants (Stored in Flash, not RAM)
const float THRESHOLD_HIGH = 75.0f;
const float ALPHA = 0.2f; // Smoothing factor for EMA filter

class EdgeController {
private:
    float filteredValue;
    bool isInitialized;

public:
    EdgeController() : filteredValue(0.0f), isInitialized(false) {}

    // Exponential Moving Average Filter: O(1) space complexity
    float filter(float rawValue) {
        if (!isInitialized) {
            filteredValue = rawValue;
            isInitialized = true;
        } else {
            filteredValue = (ALPHA * rawValue) + ((1.0f - ALPHA) * filteredValue);
        }
        return filteredValue;
    }

    void process(float rawSensorData) {
        float val = filter(rawSensorData);

        // Actuator Logic
        if (val > THRESHOLD_HIGH) {
            triggerActuator(true);
        } else {
            triggerActuator(false);
        }
    }

    void triggerActuator(bool state) {
        // In a real system, this would be: digitalWrite(PIN_RELAY, state);
        std::cout << "Actuator State: " << (state ? "ON" : "OFF") 
                  << " (Filtered Value: " << filteredValue << ")" << std::endl;
    }
};

int main() {
    EdgeController controller;

    // Simulated sensor stream
    float sensorStream[] = {70.0, 72.0, 76.0, 78.0, 74.0};

    for (float val : sensorStream) {
        controller.process(val);
    }

    return 0;
}
```

