class MovingAverageFilter {
private:
    float buffer[WINDOW_SIZE] = {0};
    int index = 0;
    float sum = 0;

public:
    float process(float newValue) {
        sum -= buffer[index];
        buffer[index] = newValue;
        sum += buffer[index];
        index = (index + 1) % WINDOW_SIZE;
        return sum / WINDOW_SIZE;
    }
};

