import * as THREE from 'https://unpkg.com/three@0.158.0/build/three.module.js';

// 1. Setup Scene
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// 2. Custom Shader Material
const vertexShader = `
    varying vec2 vUv;
    void main() {
        vUv = uv;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
`;

const fragmentShader = `
    uniform float uTime;
    varying vec2 vUv;
    void main() {
        // Create a dynamic color pulse effect
        vec3 color = vec3(0.5 + 0.5 * sin(uTime), vUv.x, vUv.y);
        gl_FragColor = vec4(color, 1.0);
    }
`;

const material = new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 } },
    vertexShader,
    fragmentShader
});

// 3. Create Mesh
const geometry = new THREE.IcosahedronGeometry(1, 15);
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);

// 4. Add Dynamic Lighting
const pointLight = new THREE.PointLight(0xffffff, 1);
pointLight.position.set(5, 5, 5);
scene.add(pointLight);
scene.add(new THREE.AmbientLight(0x404040));

camera.position.z = 3;

// 5. Animation Loop
function animate(time) {
    requestAnimationFrame(animate);

    // Update shader time
    material.uniforms.uTime.value = time * 0.002;

    // Rotate mesh
    mesh.rotation.y += 0.01;

    renderer.render(scene, camera);
}

animate();
```

### Key Concepts Explained:

*   **`ShaderMaterial`**: This allows you to write your own GPU code. 
    *   **Vertex Shader**: Handles the position of vertices (the geometry shape).
    *   **Fragment Shader**: Handles the color of every individual pixel. By passing `uTime` as a uniform, we create the "real-time" animation effect.
*   **`IcosahedronGeometry`**: A high-detail sphere-like shape that reacts well to lighting and shader distortions.
*   **`requestAnimationFrame`**: This is the heartbeat of the viewer. It syncs the rendering with the user's monitor refresh rate (usually 60Hz or 144Hz).

