```csharp
using System.Collections.Generic;
using UnityEngine;

public class CustomPhysicsWorld : MonoBehaviour
{
    public Vector3 gravity = new Vector3(0, -9.81f, 0);
    private List<CustomRigidBody> bodies = new List<CustomRigidBody>();

    public void Register(CustomRigidBody body) => bodies.Add(body);

    void FixedUpdate()
    {
        float dt = Time.fixedDeltaTime;

        foreach (var body in bodies)
        {
            // 1. Apply Gravity
            if (body.useGravity) body.ApplyForce(gravity * body.mass);

            // 2. Integrate Velocity (v = v + (F/m) * dt)
            Vector3 acceleration = body.force / body.mass;
            body.velocity += acceleration * dt;

            // 3. Integrate Position (p = p + v * dt)
            body.transform.position += body.velocity * dt;

            // 4. Reset Forces
            body.force = Vector3.zero;
        }
    }
}
```

