struct PhysicsBody {
    glm::vec3 velocity;
    glm::vec3 force;
    float mass;
    float inverseMass; // 1/mass (precomputed for performance)
    bool isStatic;

    PhysicsBody(float m) : mass(m), velocity(0), force(0), isStatic(m == 0.0f) {
        inverseMass = isStatic ? 0.0f : 1.0f / mass;
    }

    void ApplyForce(const glm::vec3& f) {
        if (!isStatic) force += f;
    }
};
