using UnityEngine;

public class PhysicsPluginManager : MonoBehaviour
{
    public static PhysicsPluginManager Instance;
    private List<CustomPhysicsBody> bodies = new List<CustomPhysicsBody>();

    public Vector3 globalGravity = new Vector3(0, -9.81f, 0);

    void Awake() => Instance = this;

    public void Register(CustomPhysicsBody body) => bodies.Add(body);
    public void Unregister(CustomPhysicsBody body) => bodies.Remove(body);

