        foreach (var body in bodies)
        {
            // 1. Apply Forces (Gravity)
            if (body.useGravity)
            {
                body.velocity += globalGravity * dt;
            }

            // 2. Integration (Euler Integration)
            body.transform.position += body.velocity * dt;

            // 3. Simple Floor Collision (Example)
            if (body.transform.position.y < 0)
            {
                body.transform.position = new Vector3(body.transform.position.x, 0, body.transform.position.z);
                body.velocity.y *= -0.5f; // Bounce
            }
        }
    }
}
