            float displacementMultiplier = Mathf.Clamp01((fluidLevel - transform.position.y) / 2f);
            Vector3 buoyancyForce = -Physics.gravity * (displacementMultiplier * density);
            _rb.AddForce(buoyancyForce, ForceMode.Acceleration);
        }
    }
}
