### 3. The Implementation (`PhysicsPlugin.cpp`)
Here we implement **Semi-Implicit Euler Integration**, the industry standard for game physics because it is more stable than explicit Euler.

```cpp
#include "PhysicsPlugin.h"

void PhysicsSystem::AddBody(PhysicsBody* body) {
    bodies.push_back(body);
}

void PhysicsSystem::Update(float deltaTime) {
    for (auto& body : bodies) {
        if (body->isStatic) continue;

        // 1. Calculate Acceleration (F = ma -> a = F/m)
        glm::vec3 acceleration = body->force / body->mass;

        // 2. Add Gravity
        acceleration += gravity;

        // 3. Update Velocity (v = v + a * dt)
        body->velocity += acceleration * deltaTime;

        // 4. Update Position (p = p + v * dt)
        body->position += body->velocity * deltaTime;

        // 5. Reset forces for next frame
        body->force = glm::vec3(0.0f);
    }
}
