class PhysicsWorld {
    std::vector<PhysicsBody*> bodies;
    float gravity = -9.81f;

public:
    void Step(float deltaTime) {
        for (auto* body : bodies) {
            if (body->invMass == 0) continue; // Skip static objects

            // 1. Apply Gravity
            body->ApplyForce({0, body->mass * gravity, 0});

            // 2. Semi-Implicit Euler Integration
            body->velocity += (body->force * body->invMass) * deltaTime;
            body->position += body->velocity * deltaTime;

            // 3. Reset forces
            body->force = {0, 0, 0};
        }
    }
};
```

