### 2. The Implementation (`CustomPhysicsComponent.cpp`)
This is where the physics integration (Euler integration) happens.

```cpp
#include "CustomPhysicsComponent.h"

CustomPhysicsComponent::CustomPhysicsComponent() 
    : velocity(0, 0, 0), acceleration(0, 0, 0), mass(1.0f), drag(0.1f) {}

void CustomPhysicsComponent::OnUpdate(float deltaTime) {
    // 1. Apply Drag (Simple air resistance)
    acceleration -= velocity * drag;

    // 2. Integrate Velocity (v = v + a * dt)
    velocity += acceleration * deltaTime;

    // 3. Integrate Position (p = p + v * dt)
    // GetOwner() refers to the GameObject/Actor this component is attached to
    Vector3 currentPos = GetOwner()->GetPosition();
    GetOwner()->SetPosition(currentPos + (velocity * deltaTime));

    // 4. Reset acceleration for next frame
    acceleration = Vector3(0, 0, 0);
}

void CustomPhysicsComponent::ApplyForce(Vector3 force) {
    // F = ma -> a = F / m
    acceleration += force / mass;
}
```

