This is where the math happens. We use a simple Euler integration for this example.

```cpp
class PhysicsWorld {
public:
    glm::vec3 gravity = {0.0f, -9.81f, 0.0f};

    void Step(float deltaTime, std::vector<PhysicsBody*>& bodies, std::vector<Transform*>& transforms) {
        for (size_t i = 0; i < bodies.size(); ++i) {
            if (bodies[i]->isStatic) continue;

            // 1. Apply Gravity
            bodies[i]->ApplyForce(gravity * bodies[i]->mass);

            // 2. Integrate Velocity (v = v + (f/m) * dt)
            bodies[i]->velocity += (bodies[i]->force / bodies[i]->mass) * deltaTime;

            // 3. Integrate Position (p = p + v * dt)
            transforms[i]->position += bodies[i]->velocity * deltaTime;

            // 4. Reset Forces
            bodies[i]->force = {0, 0, 0};
        }
    }
};
```

