class GravitySystem {
public:
    void Update(float deltaTime, EntityManager& entities) {
        // 1. Query all entities with a GravityComponent
        auto gravityWells = entities.Query<GravityComponent, TransformComponent>();

        for (auto& [gravity, transform] : gravityWells) {
            if (!gravity.isActive) continue;

            // 2. Apply force to all other physical objects in the scene
            auto physicalObjects = entities.Query<RigidBodyComponent, TransformComponent>();

            for (auto& [rb, targetTransform] : physicalObjects) {
                ApplyGravity(gravity, transform, rb, targetTransform);
            }
        }
    }

private:
    void ApplyGravity(GravityComponent& g, TransformComponent& gTrans, 
                      RigidBodyComponent& rb, TransformComponent& tTrans) {

        Vector3 direction = gTrans.position - tTrans.position;
        float distance = direction.Length();

        if (distance < g.radius) {
            Vector3 force = direction.Normalized() * (g.strength / (distance * distance));
            rb.AddForce(force); // Interface with the engine's physics solver
        }
    }
};
```

