// PhysicsBody.h
class PhysicsBody {
public:
    Vector3 velocity;
    float mass;
    bool isStatic;

    void ApplyForce(Vector3 force) {
        // F = ma -> a = F/m
        acceleration += force / mass;
    }

    void Update(float deltaTime) {
        if (isStatic) return;
        velocity += acceleration * deltaTime;
        position += velocity * deltaTime;
        acceleration = Vector3::Zero(); // Reset
    }
};
```

