    glm::vec3 velocity;
    glm::vec3 force;
    float mass;

    void ApplyForce(glm::vec3 f) { force += f; }

    void Integrate(float dt) {
        // Semi-implicit Euler integration
        glm::vec3 acceleration = force / mass;
        velocity += acceleration * dt;
        position += velocity * dt;

