### 1. The Physics World (The "Engine")
This script manages the global physics state.

```csharp
using System.Collections.Generic;
using UnityEngine;

public class SimplePhysicsWorld : MonoBehaviour
{
    public static SimplePhysicsWorld Instance;
    public Vector3 Gravity = new Vector3(0, -9.81f, 0);
    private List<PhysicsBody> bodies = new List<PhysicsBody>();

    void Awake() => Instance = this;

    public void Register(PhysicsBody body) => bodies.Add(body);

    void FixedUpdate()
    {
        foreach (var body in bodies)
        {
            // Apply Gravity
            body.Velocity += Gravity * Time.fixedDeltaTime;
            // Apply Velocity to Position
            body.transform.position += body.Velocity * Time.fixedDeltaTime;
        }
    }
}
```

### 2. The Physics Body (The "Component")
This is the component you attach to any GameObject you want to be affected by your custom physics.

```csharp
using UnityEngine;

public class PhysicsBody : MonoBehaviour
{
    public Vector3 Velocity;

    void Start()
    {
        // Register with our custom world
        SimplePhysicsWorld.Instance.Register(this);
    }
}
```

