```typescript
// src/infrastructure/external/legacy-system.gateway.ts
import { Injectable, Logger } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { CircuitBreaker } from 'opossum'; // Enterprise resilience

@Injectable()
export class LegacySystemGateway {
  private readonly logger = new Logger(LegacySystemGateway.name);
  private breaker: CircuitBreaker;

  constructor(private http: HttpService) {
    this.breaker = new CircuitBreaker(this.fetchData.bind(this), {
      timeout: 3000,
      errorThresholdPercentage: 50,
      resetTimeout: 30000,
    });
  }

  async getEmployeeData(id: string) {
    return this.breaker.fire(id).catch((err) => {
      this.logger.error(`Legacy system unavailable: ${err.message}`);
      throw new Error('Service Unavailable');
    });
  }

  private async fetchData(id: string) {
    const { data } = await this.http.axiosRef.get(`/legacy/users/${id}`);
    return data;
  }
}
```

