```typescript
// src/infrastructure/external-api.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { retry, timeout } from 'rxjs/operators';

@Injectable()
export class LegacySystemClient {
  private readonly logger = new Logger(LegacySystemClient.name);

  constructor(private readonly http: HttpService) {}

  async fetchCorporateData(id: string) {
    // Implementing resilience: 3 retries, 5s timeout
    const request$ = this.http.get(`/legacy-api/data/${id}`).pipe(
      timeout(5000),
      retry(3)
    );

    try {
      const response = await firstValueFrom(request$);
      return response.data;
    } catch (error) {
      this.logger.error(`Failed to reach legacy system: ${error.message}`);
      throw new Error('CORPORATE_SYSTEM_UNAVAILABLE');
    }
  }
}
```

