```typescript
// src/services/corporate-sync.service.ts
import { Injectable, Logger } from '@nestjs/common';
import CircuitBreaker from 'opossum';

@Injectable()
export class CorporateSyncService {
  private readonly logger = new Logger(CorporateSyncService.name);
  private breaker: CircuitBreaker;

  constructor() {
    this.breaker = new CircuitBreaker(this.syncToLegacySystem, {
      timeout: 3000,
      errorThresholdPercentage: 50,
      resetTimeout: 30000,
    });
  }

  private async syncToLegacySystem(data: any) {
    // Integration with existing SOAP/REST corporate mainframe
    return fetch('https://legacy-api.corp.internal/sync', { method: 'POST', body: JSON.stringify(data) });
  }

  async sync(data: any) {
    return this.breaker.fire(data).catch((err) => {
      this.logger.error('Circuit breaker tripped', err);
      throw new Error('Corporate system unavailable');
    });
  }
}
```

