import Fastify from 'fastify';
import { z } from 'zod';

const fastify = Fastify({ logger: true });

// 1. Define strict schema for incoming requests
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  role: z.enum(['admin', 'user', 'guest']),
});

type User = z.infer<typeof UserSchema>;

// 2. Mock Integration with Corporate System (e.g., Auth/DB)
const fetchCorporateUser = async (id: string): Promise<User> => {
  // In reality, this calls an internal gRPC or REST service
  return { id, email: 'dev@enterprise.com', role: 'admin' };
};

// 3. Route with Type-Safe validation
fastify.get<{ Params: { id: string } }>('/user/:id', async (request, reply) => {
  const { id } = request.params;

  try {
    const user = await fetchCorporateUser(id);

    // Validate against schema before returning to ensure data integrity
    const validatedUser = UserSchema.parse(user);
    return validatedUser;
  } catch (err) {
    return reply.status(400).send({ error: 'Invalid data from corporate system' });
  }
});

// 4. Start Server
const start = async () => {
  try {
    await fastify.listen({ port: 3000 });
  } catch (err) {
    fastify.log.error(err);
    process.exit(1);
  }
};

start();
```

